import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                buflen = -1;
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            long val = 0;
            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return val;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        long pLong = sc.nextLong();
        if (pLong == -1) {
            out.flush();
            return;
        }
        int P = (int) pLong;

        for (int i = 0; i < P; i++) {
            long L = sc.nextLong();
            long A = sc.nextLong();
            long B = sc.nextLong();

            // João quer maximizar o número de rodadas k (k >= 1).
            // Para completar k rodadas, a soma das primeiras m = k - 1 rodadas
            // deve ser estritamente menor que L, e m <= B - A.
            // Para minimizar a soma, escolhemos os m menores valores: A, A+1, ..., A+m-1.
            // S(m) = m * A + m * (m - 1) / 2.
            // Como L <= 10^13 e A >= 1, m não passa de ~5 * 10^6.

            long maxM = B - A;
            if (maxM > 5000000L) {
                maxM = 5000000L;
            }

            long low = 0;
            long high = maxM;
            long bestM = 0;

            while (low <= high) {
                long mid = (low + high) >>> 1;
                long sum = mid * A + mid * (mid - 1) / 2;
                if (sum < L) {
                    bestM = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            out.println(bestM + 1);
        }

        out.flush();
    }
}
